/* Standard LMDB cursor positions following deletion. This source is compiled
 * unchanged against both pinned LMDB releases and the ULMDB adapter. */
#include <lmdb.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#define REQUIRE(x) do{if(!(x)){fprintf(stderr,"%s:%d: %s\n",__FILE__,__LINE__,#x);exit(1);}}while(0)
#define OK(x) do{int r_=(x);if(r_){fprintf(stderr,"%s:%d: %s: %d %s\n",__FILE__,__LINE__,#x,r_,mdb_strerror(r_));exit(1);}}while(0)
static MDB_val text(const char*s){MDB_val v={strlen(s),(void*)s};return v;}
static void put(MDB_txn*t,MDB_dbi d,const char*k,const char*v){MDB_val key=text(k),value=text(v);OK(mdb_put(t,d,&key,&value,0));}
static void seek(MDB_cursor*c,const char*k,const char*v){MDB_val key=text(k),value=v?text(v):text("");OK(mdb_cursor_get(c,&key,&value,v?MDB_GET_BOTH:MDB_SET));}
static void trace(const char*label,MDB_cursor*c,MDB_cursor_op op){MDB_val key={0,NULL},value={0,NULL};int result=mdb_cursor_get(c,&key,&value,op);printf("%s %u %d",label,(unsigned)op,result);if(!result)printf(" %.*s=%.*s",(int)key.mv_size,(char*)key.mv_data,(int)value.mv_size,(char*)value.mv_data);putchar('\n');}
static void scenario(MDB_env*env,MDB_dbi db,const char*label,const char*k,const char*v,unsigned flags,const MDB_cursor_op*ops,size_t count,int external,int insert){MDB_txn*t;MDB_cursor*c,*other=NULL;OK(mdb_txn_begin(env,NULL,0,&t));OK(mdb_cursor_open(t,db,&c));seek(c,k,v);if(external==1){OK(mdb_cursor_open(t,db,&other));seek(other,k,v);OK(mdb_cursor_del(other,flags));}else if(external==2){MDB_val key=text(k),value=v?text(v):text("");OK(mdb_del(t,db,&key,v?&value:NULL));}else OK(mdb_cursor_del(c,flags));if(insert)put(t,db,"bb","BB");for(size_t i=0;i<count;i++)trace(label,c,ops[i]);if(other)mdb_cursor_close(other);mdb_cursor_close(c);mdb_txn_abort(t);}
int main(int argc,char**argv){REQUIRE(argc==2);MDB_env*env;MDB_txn*t;MDB_dbi kv,dup;OK(mdb_env_create(&env));OK(mdb_env_set_maxdbs(env,8));OK(mdb_env_open(env,argv[1],MDB_NOTLS,0600));OK(mdb_txn_begin(env,NULL,0,&t));OK(mdb_dbi_open(t,"kv",MDB_CREATE,&kv));OK(mdb_dbi_open(t,"dup",MDB_CREATE|MDB_DUPSORT,&dup));put(t,kv,"a","A");put(t,kv,"b","B");put(t,kv,"c","C");put(t,kv,"d","D");put(t,dup,"g","a");put(t,dup,"g","b");put(t,dup,"g","c");put(t,dup,"k","x");put(t,dup,"z","u");put(t,dup,"z","v");OK(mdb_txn_commit(t));
const MDB_cursor_op current[]={MDB_GET_CURRENT,MDB_NEXT,MDB_PREV,MDB_PREV};const MDB_cursor_op next[]={MDB_NEXT,MDB_PREV,MDB_NEXT};const MDB_cursor_op last[]={MDB_GET_CURRENT,MDB_NEXT,MDB_PREV,MDB_GET_CURRENT};const MDB_cursor_op within[]={MDB_NEXT_DUP,MDB_PREV_DUP,MDB_NEXT_DUP};const MDB_cursor_op moved[]={MDB_GET_CURRENT,MDB_NEXT_DUP,MDB_PREV_DUP};
scenario(env,kv,"kv-middle", "b",NULL,0,current,4,0,0);scenario(env,kv,"kv-next","b",NULL,0,next,3,0,0);scenario(env,kv,"kv-first","a",NULL,0,current,4,0,0);scenario(env,kv,"kv-last","d",NULL,0,last,4,0,0);scenario(env,kv,"kv-external","b",NULL,0,current,4,1,0);scenario(env,kv,"kv-external-insert","b",NULL,0,current,4,1,1);scenario(env,kv,"kv-api-delete-insert","b",NULL,0,current,4,2,1);
scenario(env,dup,"dup-middle","g","b",0,current,4,0,0);scenario(env,dup,"dup-next","g","b",0,within,3,0,0);scenario(env,dup,"dup-last-value","g","c",0,last,4,0,0);scenario(env,dup,"dup-all","g","b",MDB_NODUPDATA,current,4,0,0);scenario(env,dup,"dup-single-key","k","x",0,moved,3,0,0);scenario(env,dup,"dup-external","g","b",0,current,4,1,0);scenario(env,dup,"dup-api-delete","g","b",0,current,4,2,0);
OK(mdb_txn_begin(env,NULL,0,&t));MDB_cursor*c;OK(mdb_cursor_open(t,kv,&c));for(const char**p=(const char*[]){"a","b","c",NULL};*p;p++){MDB_val key=text(*p);OK(mdb_del(t,kv,&key,NULL));}seek(c,"d",NULL);OK(mdb_cursor_del(c,0));for(size_t i=0;i<4;i++)trace("kv-only",c,last[i]);mdb_cursor_close(c);mdb_txn_abort(t);mdb_env_close(env);return 0;}
